// Test de connexion Quartix QWS v2 : lecture seule (auth + GET uniquement). Aucun jeton ni mot de passe dans la sortie.
const a = $input.first().json;
const base = 'https://qws.quartix.net/v2/api';
const enc = o => Object.keys(o).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(o[k] == null ? '' : String(o[k]))).join('&');
const err = (e) => ({ erreur: String(e.message || e), code: e.httpCode || e.statusCode || null, detail: (e.response && e.response.body) || e.description || null });
let auth;
try {
  auth = await this.helpers.httpRequest({ method: 'POST', url: base + '/auth', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: enc({ CustomerID: a.customer_id, UserName: a.identifiant, Password: a.mot_de_passe, Application: a.application }), json: true });
} catch (e) { return [{ json: { etape: 'auth', ...err(e) } }]; }
const d = (auth && (auth.data || auth.Data)) || {};
const tok = d.accessToken || d.AccessToken;
if (!tok) return [{ json: { etape: 'auth', erreur: 'pas de jeton', cles: Object.keys(auth || {}), meta: auth && auth.meta } }];
const H = { AccessToken: tok };
const get = async (p) => { try { return await this.helpers.httpRequest({ method: 'GET', url: base + p, headers: H, json: true }); } catch (e) { return err(e); } };
const jour = $now.setZone('Europe/Paris').toFormat('yyyy-MM-dd');
return [{ json: {
  auth: 'OK',
  vehicules: await get('/vehicles'),
  live: await get('/vehicles/live'),
  trajets_du_jour: await get('/vehicles/trips?StartDay=' + jour + '&EndDay=' + jour),
  gestion: await get('/vehicles/management')
} }];
